import { NextResponse } from "next/server";
import { promises as fs } from "node:fs";
import path from "node:path";
import { getSessionUser } from "@/lib/auth/session";
import { assertScopeAllowed, assertScopeReadable, canManageScope, scopeWikiPrefix } from "@/lib/acl/scope";
import { wikiAbsPath, assertInScope } from "@/lib/wiki/paths";
import { assertWikiReady, commitAll, withWikiWriteLock } from "@/lib/wiki/repo";
import { prisma } from "@/lib/db";
import { ingestModelChoice } from "@/lib/models";

// 위키 탭 리더 — scope 위키의 폴더 트리(파일 목록) + 단일 페이지 본문. ACL 강제지점2(페이지 로드).
export const runtime = "nodejs";

async function listMd(absDir: string, relBase: string): Promise<string[]> {
  let entries: import("node:fs").Dirent[];
  try {
    entries = await fs.readdir(absDir, { withFileTypes: true });
  } catch {
    return [];
  }
  const out: string[] = [];
  for (const e of entries) {
    if (e.name.startsWith(".")) continue;
    const rel = `${relBase}/${e.name}`;
    if (e.isDirectory()) out.push(...(await listMd(path.join(absDir, e.name), rel)));
    else if (e.name.endsWith(".md")) out.push(rel);
  }
  return out;
}

export async function GET(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const url = new URL(req.url);
  const scope = url.searchParams.get("scope") ?? "";
  const pagePath = url.searchParams.get("path");

  // ACL 강제지점2: 페이지 로드 — 허용 scope + ★아카이브 룸은 읽기 전용 열람 허용★(쓰기는 PUT에서 별도 차단)
  try {
    await assertScopeReadable(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);

  // 단일 페이지 본문
  if (pagePath) {
    try {
      assertInScope(wikiScope, pagePath);
    } catch {
      return NextResponse.json({ error: "scope 밖 경로입니다." }, { status: 400 });
    }
    if (!pagePath.endsWith(".md")) return NextResponse.json({ error: "md 파일만 열람합니다." }, { status: 400 });
    try {
      const content = await fs.readFile(wikiAbsPath(pagePath), "utf8");
      // 이 페이지가 인용한 원본 자료(frontmatter sources의 sha) → 위키에서 원본 열람·이미지 표시용
      const shas = [...content.matchAll(/sha256:([a-f0-9]{64})/g)].map((m) => m[1]);
      let sources: { id: number; title: string; type: string; createdAt: string }[] = [];
      // 이 페이지가 '원본 그대로'(RAW_IMPORT)로 들어온, ★아직 분석 안 된★ 자료에서 만들어졌는지 → [AI로 분석] 배너용.
      let rawImport = false;
      let rawSourceId: number | null = null;
      if (shas.length) {
        const rows = await prisma.source.findMany({
          where: { sha256: { in: shas }, teamScope: wikiScope },
          select: { id: true, title: true, type: true, createdAt: true, ingestJobs: { orderBy: { id: "desc" }, take: 1, select: { gate: true, status: true } } },
          orderBy: { id: "asc" },
        });
        // createdAt = 이 자료가 추가된 시각(UTC ISO로 보냄 → 화면에서 KST로 표시). 원본 자료 리스트에 누적 표시.
        sources = rows.map((r) => ({ id: r.id, title: r.title, type: r.type, createdAt: r.createdAt.toISOString() }));
        const raw = rows.find((r) => r.ingestJobs[0]?.gate === "RAW_IMPORT" && r.ingestJobs[0]?.status === "APPLIED");
        if (raw) { rawImport = true; rawSourceId = raw.id; }
      }
      // 배너에 띄울 자동 분석 모델·사유(원본 그대로 페이지일 때만).
      const analyzeModel = rawImport ? await ingestModelChoice() : null;
      // ★공통 승격 상태★ — 룸(project) 페이지가 이미 공통으로 승격 요청/반영됐는지(PENDING|APPROVED|REJECTED|null).
      //   이미 PENDING/APPROVED면 '공통으로 승격 요청' 버튼 대신 상태를 보여 중복 요청을 막는다.
      let promotionStatus: string | null = null;
      if (wikiScope.startsWith("project-")) {
        const promo = await prisma.promotion.findFirst({
          where: { fromScope: wikiScope, path: pagePath },
          orderBy: { id: "desc" }, select: { status: true },
        });
        promotionStatus = promo?.status ?? null;
      }
      return NextResponse.json({ path: pagePath, content, sources, rawImport, rawSourceId, analyzeModel, promotionStatus });
    } catch {
      return NextResponse.json({ error: "페이지를 찾을 수 없습니다." }, { status: 404 });
    }
  }

  // 폴더 트리(파일 경로 목록) + 각 페이지의 원본 자료 타입(첫 인용 sha) → 트리 아이콘 구분
  const files = (await listMd(wikiAbsPath(wikiScope), wikiScope)).sort();
  const fileSha: Record<string, string> = {};
  const titles: Record<string, string> = {}; // 경로→제목(위키 내부 [[링크]] 해석용)
  const updated: Record<string, string> = {}; // 경로→frontmatter updated(트리 최신순 정렬·질의 일자그룹 키)
  const shaSet = new Set<string>();
  await Promise.all(
    files.map(async (f) => {
      const base = f.split("/").pop();
      if (base === "index.md" || base === "log.md") return;
      try {
        const c = await fs.readFile(wikiAbsPath(f), "utf8");
        const m = c.match(/sha256:([a-f0-9]{64})/);
        if (m) { fileSha[f] = m[1]; shaSet.add(m[1]); }
        const fm = c.match(/^---\n([\s\S]*?)\n---/); // frontmatter title 추출(있으면)
        const tm = fm && fm[1].match(/^title:\s*(.+)$/m);
        if (tm) titles[f] = tm[1].trim().replace(/^["']|["']$/g, "");
        const um = fm && fm[1].match(/^updated:\s*(.+)$/m);
        if (um) updated[f] = um[1].trim().replace(/^["']|["']$/g, "");
      } catch { /* skip */ }
    }),
  );
  const types: Record<string, string> = {};
  if (shaSet.size) {
    const rows = await prisma.source.findMany({
      where: { teamScope: wikiScope, sha256: { in: [...shaSet] } },
      select: { sha256: true, type: true },
    });
    const shaType: Record<string, string> = {};
    for (const r of rows) shaType[r.sha256] = r.type;
    for (const [f, sha] of Object.entries(fileSha)) if (shaType[sha]) types[f] = shaType[sha];
  }
  return NextResponse.json({ scope: wikiScope, files, types, titles, updated });
}

// PUT {scope, path, content} — 위키 페이지 직접 편집(교정용). 룸 관리자만(canManageScope).
// 단일 라이터(withWikiWriteLock+commitAll)로 커밋 → git 이력이 곧 되돌리기(docs/13). 상호링크·index 자동정리는 안 함.
export async function PUT(req: Request) {
  const user = await getSessionUser();
  if (!user) return NextResponse.json({ error: "로그인이 필요합니다." }, { status: 401 });
  const body = await req.json().catch(() => ({}));
  const scope = typeof body.scope === "string" ? body.scope : "";
  const pagePath = typeof body.path === "string" ? body.path : "";
  const content = body.content;
  if (typeof content !== "string") return NextResponse.json({ error: "content가 필요합니다." }, { status: 400 });
  if (!pagePath.endsWith(".md")) return NextResponse.json({ error: "md 페이지만 편집합니다." }, { status: 400 });
  try {
    await assertScopeAllowed(user, scope);
  } catch {
    return NextResponse.json({ error: "접근 권한이 없는 scope입니다." }, { status: 403 });
  }
  const wikiScope = scopeWikiPrefix(scope);
  if (!(await canManageScope(user, wikiScope))) {
    return NextResponse.json({ error: "이 룸의 관리자만 편집할 수 있습니다 (OWNER·ADMIN)." }, { status: 403 });
  }
  try {
    assertInScope(wikiScope, pagePath);
  } catch {
    return NextResponse.json({ error: "scope 밖 경로입니다." }, { status: 400 });
  }
  const abs = wikiAbsPath(pagePath);
  try {
    await fs.access(abs); // 편집은 ★기존 페이지★만(새 페이지 생성 경로 아님)
  } catch {
    return NextResponse.json({ error: "페이지를 찾을 수 없습니다." }, { status: 404 });
  }
  await assertWikiReady();
  const sha = await withWikiWriteLock(async () => {
    await fs.writeFile(abs, content, "utf8");
    return commitAll(`edit-page(${wikiScope}): ${pagePath}`, { team: wikiScope, gate: "EDITED", model: "(직접편집)" });
  });
  return NextResponse.json({ ok: true, commit: sha });
}

