export function renderMarkdown(
  md: string,
  onLink?: (target: string) => void,
  lineNumbers = false,
  linkOk?: (target: string) => boolean,
  sources?: { sha256: string; id: number; title: string; type?: string }[],
): ReactNode {
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  const out: ReactNode[] = [];
  let i = 0, key = 0, rowKey = 0;
  // 불릿 텍스트가 `sha256:<hash> (선택 부가설명)` 이고 매핑되는 원본이 있으면 제목 링크로. 아니면 null.
  const shaMap = new Map((sources ?? []).map((s) => [s.sha256, s]));
  const sourceRef = (text: string): ReactNode | null => {
    const m = text.match(/^sha256:([a-f0-9]{64})\b\s*(.*)$/);
    if (!m) return null;
    const src = shaMap.get(m[1]);
    if (!src) return null; // DB에 없는 sha(타 scope·삭제 등) → 폴백
    const rest = (m[2] || "").trim();
    return (
      <span className="md-srcref">
        <a className="md-link" href={`/api/materials/${src.id}/raw`} target="_blank" rel="noreferrer" title="원본 자료 열기">{src.title}</a>
        {src.type ? <span className="md-srcref-type"> ({src.type})</span> : null}
        {rest ? " " + rest : ""}
      </span>
    );
  };

