import type { ReactNode } from "react";

// 경량 markdown 렌더(heading·bold·inline code·list·[[link]]·image·frontmatter·code block).
// 위키 리더와 질의 답변에서 공용으로 쓴다. 외부 라이브러리 없이 안전한 부분집합만 처리.

// onLink(target): 위키 내부 링크([[name]]·[text](path)) 클릭 시 호출(WikiTab이 해당 페이지로 이동).
// 없으면(질의 답변 등) 링크는 비클릭 파란 글자로만 표시(기존 동작).
// linkOk(target): 내부 위키링크([[ ]]·[](경로))가 실제 페이지로 연결되는지. false면 ★죽은(미생성) 링크★로 흐리게.
export function inlineMd(s: string, onLink?: (target: string) => void, linkOk?: (target: string) => boolean): ReactNode {
  const parts: ReactNode[] = [];
  // ★순서가 중요★: 이미지 → 위키링크 → 일반링크 → 코드 → 굵게(**) → 취소선(~~) → 기울임(*,_) → 자동링크.
  //   - 코드를 기울임보다 먼저 둬 `a*b`의 별표를 코드가 보호. 굵게(**)를 기울임(*)보다 먼저.
  //   - 기울임 *…*: 여는 별표 뒤가 공백/별표면 제외, 닫는 별표 앞이 공백이면 제외 → "2 * 3", "*.md and *.txt" 같은 오탐 방지.
  //   - 기울임 _…_: 양옆이 단어/한글이면 제외 → snake_case·파일_이름·URL 안 깨짐.
  const re = /!\[[^\]]*\]\([^)]+\)|\[\[[^\]]+\]\]|\[[^\]]+\]\([^)]+\)|`[^`]+`|\*\*[^*]+\*\*|~~[^~]+~~|\*(?![\s*])[^*\n]*?(?<!\s)\*|(?<![\w가-힣])_(?![\s_])[^_\n]*?(?<!\s)_(?![\w가-힣])|https?:\/\/[^\s<>()\[\]]+/g;
  let last = 0, k = 0, m: RegExpExecArray | null;
  const link = (label: string, target: string) => {
    if (/^https?:\/\//i.test(target)) return <a key={k++} className="md-link" href={target} target="_blank" rel="noreferrer">{label}</a>;
    // 내부 링크인데 연결되는 페이지가 없으면 ★죽은 링크★로 표시(클릭 비활성·흐린 점선) — '아직 페이지 없음'임을 명확히.
    if (linkOk && !linkOk(target)) return <span key={k++} className="md-link md-link-dead" title="연결된 위키 페이지가 아직 없습니다">{label}</span>;
    return onLink
      ? <button key={k++} type="button" className="md-link md-link-btn" onClick={() => onLink(target)}>{label}</button>
      : <span key={k++} className="md-link">{label}</span>;
  };
  while ((m = re.exec(s))) {
    if (m.index > last) parts.push(s.slice(last, m.index));
    const t = m[0];
    if (t.startsWith("![")) {
      const mm = t.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
      if (mm) parts.push(<img key={k++} className="md-img" src={mm[2]} alt={mm[1]} />);
    } else if (t.startsWith("[[")) {
      const name = t.slice(2, -2);
      parts.push(link(name, name));
    } else if (t.startsWith("[")) {
      const mm = t.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (mm) parts.push(link(mm[1], mm[2]));
    } else if (t.startsWith("**")) parts.push(<b key={k++}>{inlineMd(t.slice(2, -2), onLink, linkOk)}</b>);
    else if (t.startsWith("~~")) parts.push(<del key={k++} className="md-del">{inlineMd(t.slice(2, -2), onLink, linkOk)}</del>);
    else if (t.startsWith("`")) parts.push(<code key={k++} className="md-ic">{t.slice(1, -1)}</code>); // 코드 안은 그대로(마크다운 미해석)
    else if (t.startsWith("*") || t.startsWith("_")) parts.push(<em key={k++}>{inlineMd(t.slice(1, -1), onLink, linkOk)}</em>); // 굵게/기울임/취소선 안의 [[링크]]도 렌더되게 재귀
    else if (/^https?:\/\//.test(t)) parts.push(<a key={k++} className="md-link" href={t} target="_blank" rel="noreferrer">{t}</a>);
    else parts.push(t); // 안전 폴백(이론상 도달 안 함)
    last = m.index + t.length;
  }
  if (last < s.length) parts.push(s.slice(last));
  return parts;
}

// 표(GitHub식 |a|b|) 한 행을 셀 배열로. 앞뒤 파이프 제거 후 | 로 분리.
function splitRow(line: string): string[] {
  return line.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
}
// 표 구분행( |---|---| · |:--|--:| 등 ) 판정 — 대시 포함 + 파이프 포함 + 그 외엔 공백/콜론만.
function isTableSep(line: string): boolean {
  return /^[\s|:-]+$/.test(line) && line.includes("-") && line.includes("|");
}

// lineNumbers=true면 각 블록 왼쪽에 ★그 블록이 시작한 원문 소스 줄번호★ 거터를 붙인다
//   → 수정 이력 diff·원문 보기의 줄번호와 일치해 '몇 번째 줄'을 교차 확인할 수 있다.
export function renderMarkdown(md: string, onLink?: (target: string) => void, lineNumbers = false, linkOk?: (target: string) => boolean): ReactNode {
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  const out: ReactNode[] = [];
  let i = 0, key = 0, rowKey = 0;
  const emit = (node: ReactNode, lineNo: number) => {
    if (!lineNumbers) { out.push(node); return; }
    out.push(
      <div key={`L${rowKey++}`} className="md-lnrow">
        <span className="md-lnnum">{lineNo}</span>
        <div className="md-lnbody">{node}</div>
      </div>,
    );
  };
  if (lines[0] === "---") {
    const fm: string[] = []; let j = 1;
    while (j < lines.length && lines[j] !== "---") { fm.push(lines[j]); j++; }
    if (j < lines.length) { emit(<pre key={key++} className="md-fm">{fm.join("\n")}</pre>, 1); i = j + 1; }
  }
  let inCode = false; let code: string[] = []; let codeStart = 0;
  for (; i < lines.length; i++) {
    const ln = lines[i];
    if (ln.startsWith("```")) {
      if (inCode) { emit(<pre key={key++} className="md-code"><code>{code.join("\n")}</code></pre>, codeStart + 1); code = []; inCode = false; }
      else { inCode = true; codeStart = i; }
      continue;
    }
    if (inCode) { code.push(ln); continue; }
    // HTML 주석(예: <!-- ai-cost --> 마커)은 ★표시하지 않음★. 멀티라인이면 --> 까지 건너뜀.
    if (ln.trimStart().startsWith("<!--")) {
      while (!lines[i].includes("-->") && i < lines.length - 1) i++;
      continue;
    }
