  //   - 기울임 *…*: 여는 별표 뒤가 공백/별표면 제외, 닫는 별표 앞이 공백이면 제외 → "2 * 3", "*.md and *.txt" 같은 오탐 방지.
  //   - 기울임 _…_: 양옆이 단어/한글이면 제외 → snake_case·파일_이름·URL 안 깨짐.
  const re = /!\[[^\]]*\]\([^)]+\)|\[\[[^\]]+\]\]|\[[^\]]+\]\([^)]+\)|`[^`]+`|\*\*[^*]+\*\*|~~[^~]+~~|\*(?![\s*])[^*\n]*?(?<!\s)\*|(?<![\w가-힣])_(?![\s_])[^_\n]*?(?<!\s)_(?![\w가-힣])|https?:\/\/[^\s<>()\[\]]+/g;
  let last = 0, k = 0, m: RegExpExecArray | null;
  const link = (label: string, target: string) => {
    if (/^https?:\/\//i.test(target)) return <a key={k++} className="md-link" href={target} target="_blank" rel="noreferrer">{label}</a>;
    // 내부 링크인데 연결되는 페이지가 없으면 ★죽은 링크★로 표시(클릭 비활성·흐린 점선) — '아직 페이지 없음'임을 명확히.
    if (linkOk && !linkOk(target)) return <span key={k++} className="md-link md-link-dead" title="연결된 위키 페이지가 아직 없습니다">{label}</span>;
    return onLink
      ? <button key={k++} type="button" className="md-link md-link-btn" onClick={() => onLink(target)}>{label}</button>
      : <span key={k++} className="md-link">{label}</span>;
  };
  while ((m = re.exec(s))) {
    if (m.index > last) parts.push(s.slice(last, m.index));
    const t = m[0];
    if (t.startsWith("![")) {
      const mm = t.match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
      if (mm) parts.push(<img key={k++} className="md-img" src={mm[2]} alt={mm[1]} />);
    } else if (t.startsWith("[[")) {
      const name = t.slice(2, -2);
      parts.push(link(name, name));
    } else if (t.startsWith("[")) {
      const mm = t.match(/^\[([^\]]+)\]\(([^)]+)\)$/);
      if (mm) parts.push(link(mm[1], mm[2]));
    } else if (t.startsWith("**")) parts.push(<b key={k++}>{inlineMd(t.slice(2, -2), onLink, linkOk)}</b>);
    else if (t.startsWith("~~")) parts.push(<del key={k++} className="md-del">{inlineMd(t.slice(2, -2), onLink, linkOk)}</del>);
    else if (t.startsWith("`")) parts.push(<code key={k++} className="md-ic">{t.slice(1, -1)}</code>); // 코드 안은 그대로(마크다운 미해석)
    else if (t.startsWith("*") || t.startsWith("_")) parts.push(<em key={k++}>{inlineMd(t.slice(1, -1), onLink, linkOk)}</em>); // 굵게/기울임/취소선 안의 [[링크]]도 렌더되게 재귀
    else if (/^https?:\/\//.test(t)) parts.push(<a key={k++} className="md-link" href={t} target="_blank" rel="noreferrer">{t}</a>);
    else parts.push(t); // 안전 폴백(이론상 도달 안 함)
    last = m.index + t.length;
  }
  if (last < s.length) parts.push(s.slice(last));
  return parts;
}

// 표(GitHub식 |a|b|) 한 행을 셀 배열로. 앞뒤 파이프 제거 후 | 로 분리.
function splitRow(line: string): string[] {
  return line.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
}
// 표 구분행( |---|---| · |:--|--:| 등 ) 판정 — 대시 포함 + 파이프 포함 + 그 외엔 공백/콜론만.
function isTableSep(line: string): boolean {
  return /^[\s|:-]+$/.test(line) && line.includes("-") && line.includes("|");
}

// lineNumbers=true면 각 블록 왼쪽에 ★그 블록이 시작한 원문 소스 줄번호★ 거터를 붙인다
//   → 수정 이력 diff·원문 보기의 줄번호와 일치해 '몇 번째 줄'을 교차 확인할 수 있다.
// sources: 이 페이지가 인용한 원본 자료(sha256→제목·id). 있으면 '## 출처'의 `sha256:...` 줄을
//   사람이 읽을 수 있는 ★제목 + 원본 링크★로 치환한다(매핑 없으면 원래 sha를 그대로 표시 — 안전 폴백).
export function renderMarkdown(
  md: string,
  onLink?: (target: string) => void,
  lineNumbers = false,
  linkOk?: (target: string) => boolean,
  sources?: { sha256: string; id: number; title: string; type?: string }[],
): ReactNode {
  const lines = md.replace(/\r\n/g, "\n").split("\n");
  const out: ReactNode[] = [];
  let i = 0, key = 0, rowKey = 0;
  // 불릿 텍스트가 `sha256:<hash> (선택 부가설명)` 이고 매핑되는 원본이 있으면 제목 링크로. 아니면 null.
  const shaMap = new Map((sources ?? []).map((s) => [s.sha256, s]));
  const sourceRef = (text: string): ReactNode | null => {
    const m = text.match(/^sha256:([a-f0-9]{64})\b\s*(.*)$/);
    if (!m) return null;
    const src = shaMap.get(m[1]);
    if (!src) return null; // DB에 없는 sha(타 scope·삭제 등) → 폴백
    const rest = (m[2] || "").trim();
    return (
      <span className="md-srcref">
        <a className="md-link" href={`/api/materials/${src.id}/raw`} target="_blank" rel="noreferrer" title="원본 자료 열기">{src.title}</a>
        {src.type ? <span className="md-srcref-type"> ({src.type})</span> : null}
        {rest ? " " + rest : ""}
      </span>
    );
  };
  const emit = (node: ReactNode, lineNo: number) => {
    if (!lineNumbers) { out.push(node); return; }
    out.push(
      <div key={`L${rowKey++}`} className="md-lnrow">
        <span className="md-lnnum">{lineNo}</span>
        <div className="md-lnbody">{node}</div>
      </div>,
    );
  };
  if (lines[0] === "---") {
    const fm: string[] = []; let j = 1;
    while (j < lines.length && lines[j] !== "---") { fm.push(lines[j]); j++; }
    if (j < lines.length) { emit(<pre key={key++} className="md-fm">{fm.join("\n")}</pre>, 1); i = j + 1; }
  }
  let inCode = false; let code: string[] = []; let codeStart = 0;
  for (; i < lines.length; i++) {
    const ln = lines[i];
    if (ln.startsWith("```")) {
      if (inCode) { emit(<pre key={key++} className="md-code"><code>{code.join("\n")}</code></pre>, codeStart + 1); code = []; inCode = false; }
      else { inCode = true; codeStart = i; }
      continue;
    }
    if (inCode) { code.push(ln); continue; }
    // HTML 주석(예: <!-- ai-cost --> 마커)은 ★표시하지 않음★. 멀티라인이면 --> 까지 건너뜀.
    if (ln.trimStart().startsWith("<!--")) {
      while (!lines[i].includes("-->") && i < lines.length - 1) i++;
      continue;
    }
    // 인용(>) — 분석 비용 푸터 등. 연속된 > 줄을 하나의 인용 박스로 묶는다.
    if (/^\s*>\s?/.test(ln)) {
      const q = [ln.replace(/^\s*>\s?/, "")]; let j = i + 1;
      while (j < lines.length && /^\s*>\s?/.test(lines[j])) { q.push(lines[j].replace(/^\s*>\s?/, "")); j++; }
      emit(<blockquote key={key++} className="md-quote">{q.map((x, qi) => <div key={qi}>{inlineMd(x, onLink, linkOk)}</div>)}</blockquote>, i + 1);
      i = j - 1; continue;
    }
    // 표 — 헤더행 + 구분행(|---|) + 본문행들을 실제 <table>로.
    if (/^\s*\|.*\|\s*$/.test(ln) && i + 1 < lines.length && isTableSep(lines[i + 1])) {
      const header = splitRow(ln); const body: string[][] = []; let j = i + 2;
      while (j < lines.length && /^\s*\|.*\|\s*$/.test(lines[j])) { body.push(splitRow(lines[j])); j++; }
      emit(
        <table key={key++} className="md-table">
          <thead><tr>{header.map((h, hi) => <th key={hi}>{inlineMd(h, onLink, linkOk)}</th>)}</tr></thead>
          <tbody>{body.map((r, ri) => <tr key={ri}>{header.map((_, ci) => <td key={ci}>{inlineMd(r[ci] ?? "", onLink, linkOk)}</td>)}</tr>)}</tbody>
        </table>,
        i + 1,
      );
      i = j - 1; continue;
    }
    if (ln.startsWith("### ")) emit(<h4 key={key++} className="md-h3">{inlineMd(ln.slice(4), onLink, linkOk)}</h4>, i + 1);
    else if (ln.startsWith("## ")) emit(<h3 key={key++} className="md-h2">{inlineMd(ln.slice(3), onLink, linkOk)}</h3>, i + 1);
    else if (ln.startsWith("# ")) emit(<h2 key={key++} className="md-h1">{inlineMd(ln.slice(2), onLink, linkOk)}</h2>, i + 1);
    else if (/^#{4,6}\s/.test(ln)) emit(<h4 key={key++} className="md-h3">{inlineMd(ln.replace(/^#{4,6}\s+/, ""), onLink, linkOk)}</h4>, i + 1); // #### 이상은 가장 작은 제목으로
    else if (/^\s*[-*]\s+\[[ xX]\]\s/.test(ln)) { // 체크박스: - [ ] / - [x]
      const tm = ln.match(/^(\s*)[-*]\s+\[([ xX])\]\s+(.*)$/)!;
      const depth = Math.min(Math.floor(tm[1].length / 2), 6); const done = tm[2].toLowerCase() === "x";
      emit(<div key={key++} className={`md-task${done ? " done" : ""}`} style={depth ? { marginLeft: depth * 18 } : undefined}><span className="md-task-box">{done ? "☑" : "☐"}</span>{inlineMd(tm[3], onLink, linkOk)}</div>, i + 1);
    }
    else if (/^\s*[-*] /.test(ln)) { // 불릿(중첩 깊이 = 들여쓰기/2칸)
      const depth = Math.min(Math.floor((ln.match(/^\s*/)![0].length) / 2), 6);
      const text = ln.replace(/^\s*[-*] /, "");
      const sref = sourceRef(text); // '## 출처'의 sha256 줄이면 제목·링크로 치환(아니면 일반 렌더)
      emit(<div key={key++} className="md-li" style={depth ? { marginLeft: depth * 18 } : undefined}>{sref ?? inlineMd(text, onLink, linkOk)}</div>, i + 1);
    }
    // 번호 목록(1. 2. …) — 실제 번호 보존 hanging-indent + 중첩 깊이. (위키 본문에 매우 흔함)
    else if (/^\s*\d+\.\s/.test(ln)) {
      const om = ln.match(/^(\s*)(\d+)\.\s+(.*)$/)!;
      const depth = Math.min(Math.floor(om[1].length / 2), 6);
      emit(<div key={key++} className="md-oli" style={depth ? { marginLeft: depth * 18 } : undefined}><span className="md-oli-num">{om[2]}.</span>{inlineMd(om[3], onLink, linkOk)}</div>, i + 1);
    }
    else if (/^\s*(-{3,}|\*{3,}|_{3,})\s*$/.test(ln)) emit(<hr key={key++} className="md-hr" />, i + 1); // 구분선
    else if (ln.trim() === "") emit(<div key={key++} className="md-sp" />, i + 1);
    else emit(<p key={key++} className="md-p">{inlineMd(ln, onLink, linkOk)}</p>, i + 1);
  }
  if (inCode && code.length) emit(<pre key={key++} className="md-code"><code>{code.join("\n")}</code></pre>, codeStart + 1);
  return out;
}

